def evaluate(expr: str) -> float:
    """
    Evaluate an arithmetic expression containing non-negative numbers (integers or decimals),
    operators +, -, *, /, parentheses, spaces, and unary minus.
    Normal precedence: parentheses > unary +/- > * / > + -.
    """
    # ---------- Tokenizer ----------
    class Token:
        __slots__ = ('type', 'value')
        def __init__(self, type_: str, value=None):
            self.type = type_
            self.value = value
        def __repr__(self):
            return f'Token({self.type}, {self.value!r})'

    def tokenize(s: str):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c.isspace():
                i += 1
                continue
            if c.isdigit() or c == '.':
                # parse number (integer or decimal)
                start = i
                dot_seen = (c == '.')
                i += 1
                while i < n:
                    ch = s[i]
                    if ch.isdigit():
                        i += 1
                    elif ch == '.' and not dot_seen:
                        dot_seen = True
                        i += 1
                    else:
                        break
                num_str = s[start:i]
                # Convert to float (handles both int and decimal)
                tokens.append(Token('NUMBER', float(num_str)))
            elif c == '+':
                tokens.append(Token('PLUS'))
                i += 1
            elif c == '-':
                tokens.append(Token('MINUS'))
                i += 1
            elif c == '*':
                tokens.append(Token('MUL'))
                i += 1
            elif c == '/':
                tokens.append(Token('DIV'))
                i += 1
            elif c == '(':
                tokens.append(Token('LPAREN'))
                i += 1
            elif c == ')':
                tokens.append(Token('RPAREN'))
                i += 1
            else:
                raise ValueError(f'Invalid character: {c!r}')
        tokens.append(Token('EOF'))
        return tokens

    # ---------- Parser ----------
    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0
            self.current = tokens[0]

        def eat(self, token_type):
            if self.current.type == token_type:
                self.pos += 1
                if self.pos < len(self.tokens):
                    self.current = self.tokens[self.pos]
            else:
                raise ValueError(f'Expected {token_type}, got {self.current.type}')

        def parse(self):
            result = self.expression()
            if self.current.type != 'EOF':
                raise ValueError('Unexpected tokens after expression')
            return result

        # expression -> term (('+' | '-') term)*
        def expression(self):
            result = self.term()
            while self.current.type in ('PLUS', 'MINUS'):
                op = self.current.type
                self.eat(op)
                right = self.term()
                if op == 'PLUS':
                    result += right
                else:
                    result -= right
            return result

        # term -> factor (('*' | '/') factor)*
        def term(self):
            result = self.factor()
            while self.current.type in ('MUL', 'DIV'):
                op = self.current.type
                self.eat(op)
                right = self.factor()
                if op == 'MUL':
                    result *= right
                else:
                    result /= right
            return result

        # factor -> ('+' | '-') factor | primary
        def factor(self):
            if self.current.type == 'PLUS':
                self.eat('PLUS')
                return self.factor()
            if self.current.type == 'MINUS':
                self.eat('MINUS')
                return -self.factor()
            return self.primary()

        # primary -> NUMBER | '(' expression ')'
        def primary(self):
            if self.current.type == 'NUMBER':
                val = self.current.value
                self.eat('NUMBER')
                return val
            if self.current.type == 'LPAREN':
                self.eat('LPAREN')
                val = self.expression()
                self.eat('RPAREN')
                return val
            raise ValueError(f'Unexpected token: {self.current.type}')

    tokens = tokenize(expr)
    parser = Parser(tokens)
    return parser.parse()
